window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d84cc1eca92e394c"]={"versions": [{"id": "FIG-d84cc1eca92e394c", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) der <em>AUTOSAR Adaptive Platform Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>).\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Definiert die formale Modellierung der Instanziierung des Functional Clusters <strong>UCM</strong> (<em>Update and Configuration Management</em>) im <em>Machine Manifest</em>. Es verankert UCM im allgemeinen Instanziierungsbaum der Adaptive-Plattform-Module und ermöglicht die eindeutige Adressierung spezifischer UCM-Instanzen im Fahrzeugnetzwerk (gemäß <code>RS_MANI_00023</code>).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Identifiable</code></strong> <em>(abstrakt / Core-Metaklasse)</em>:\n<ul class=\"fig-list\"><li>Oberste Abstraktion für alle referenzierbaren AUTOSAR-Modellelemente.\n</li><li>Stellt Standardattribute bereit: <code>shortName</code> (Kardinalität [1], zwingend zur Pfadbildung), optionale UUIDs und Dokumentationsmetadaten.\n</li></ul>\n</li><li><strong><code>AdaptiveModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für die Konfiguration und Bereitstellung von Adaptive-Plattform-Basisdiensten bzw. Functional Clusters auf einer konkreten Ziel-Maschine (<code>Machine</code>).\n</li></ul>\n</li><li><strong><code>NonOsModuleInstantiation</code></strong> <em>(abstrakt, erbt via Generalisierung von <code>AdaptiveModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Differenziert Modulinstanzen, die keine direkten Betriebssystem-Prozesskonfigurationen (<code>OsModuleInstantiation</code> / Prozess-Scheduling) kapseln, sondern stack-interne Dienste und Functional-Cluster-Ressourcen parametrisieren.\n</li></ul>\n</li><li><strong><code>UcmModuleInstantiation</code></strong> <em>(konkret, erbt via Generalisierung von <code>NonOsModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Spezifische Manifest-Entität zur Repräsentation einer UCM-Instanz auf der jeweiligen Adaptive Platform Machine.\n</li><li><strong>Attribut:</strong>\n<ul class=\"fig-list\"><li><code>+ identifier: PositiveInteger</code> (Kardinalität [1]): Eindeutige, ganzzahlige Kennung der UCM-Instanz (<code>TPS_MANI_01226</code>, <code>TPS_MANI_01227</code>).\n</li></ul>\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li>Als statisches Metamodell-Klassendiagramm bildet die Darstellung keinen prozeduralen Ablauf ab.\n</li><li><strong>Laufzeit-Bezug:</strong>\n<ul class=\"fig-list\"><li>Der statisch konfigurierte <code>identifier</code> dient zur Laufzeit dem Routing und Dispatching von Aktualisierungspaketen.\n</li><li>In heterogenen Multi-UCM-Architekturen (z. B. zentraler <em>Vehicle Update Manager</em> steuert mehrere lokale <em>Target-UCMs</em>) prüft der UCM-Daemon bei eingehenden Software-Paketen, ob das Paket für seinen konfigurierten <code>identifier</code> bestimmt ist, bevor die Update-Zustandsmaschine (Transferring, Processing, Activating) initiiert wird.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Manifest-Erstellung &amp; XML-Schema:</strong>\n<ul class=\"fig-list\"><li>Im ARXML des <em>Machine Manifests</em> ist pro UCM-Dienstinstanz ein <code>&lt;UCM-MODULE-INSTANTIATION&gt;</code> unterhalb der jeweiligen <code>&lt;MACHINE&gt;</code> anzulegen.\n</li><li>Der Pfad erfordert einen gültigen <code>&lt;SHORT-NAME&gt;</code> (geerbt von <code>Identifiable</code>) und zwingend das Element <code>&lt;IDENTIFIER&gt;</code> mit einem ganzzahligen Wert &gt; 0.\n</li></ul>\n</li><li><strong>Stack- &amp; Integrator-Relevanz:</strong>\n<ul class=\"fig-list\"><li><strong>Generatoren / Backend:</strong> Manifest-Generatoren mappen <code>identifier</code> direkt in Konfigurations-Header, Initialisierungs-Payloads oder IPC/ara::com-Dienstinstanz-IDs des UCM-Daemons.\n</li><li><strong>Eindeutigkeit &amp; Flottenarchitektur:</strong> Der <code>identifier</code> muss im Adressbereich des Gesamtfahrzeug-Update-Managers eindeutig vergeben werden, um Fehlzustellungen von Software-Bundles und Rollbacks bei OTA-Kampagnen deterministisch zu verhindern.\n</li></ul>\n</li></ul>"}, {"id": "FIG-f5e1a0b0f072564c", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) der <em>AUTOSAR Adaptive Platform Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>).\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Definiert die formale Modellierung der Instanziierung des Functional Clusters <strong>UCM</strong> (<em>Update and Configuration Management</em>) im <em>Machine Manifest</em>. Es verankert UCM im allgemeinen Instanziierungsbaum der Adaptive-Plattform-Module und ermöglicht die eindeutige Adressierung spezifischer UCM-Instanzen im Fahrzeugnetzwerk (gemäß <code>RS_MANI_00023</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Identifiable</code></strong> <em>(abstrakt / Core-Metaklasse)</em>:\n<ul class=\"fig-list\"><li>Oberste Abstraktion für alle referenzierbaren AUTOSAR-Modellelemente.\n</li><li>Stellt Standardattribute bereit: <code>shortName</code> (Kardinalität [1], zwingend zur Pfadbildung), optionale UUIDs und Dokumentationsmetadaten.\n</li></ul>\n</li><li><strong><code>AdaptiveModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für die Konfiguration und Bereitstellung von Adaptive-Plattform-Basisdiensten bzw. Functional Clusters auf einer konkreten Ziel-Maschine (<code>Machine</code>).\n</li></ul>\n</li><li><strong><code>NonOsModuleInstantiation</code></strong> <em>(abstrakt, erbt via Generalisierung von <code>AdaptiveModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Differenziert Modulinstanzen, die keine direkten Betriebssystem-Prozesskonfigurationen (<code>OsModuleInstantiation</code> / Prozess-Scheduling) kapseln, sondern stack-interne Dienste und Functional-Cluster-Ressourcen parametrisieren.\n</li></ul>\n</li><li><strong><code>UcmModuleInstantiation</code></strong> <em>(konkret, erbt via Generalisierung von <code>NonOsModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Spezifische Manifest-Entität zur Repräsentation einer UCM-Instanz auf der jeweiligen Adaptive Platform Machine.\n</li><li><strong>Attribut:</strong>\n<ul class=\"fig-list\"><li><code>+ identifier: String</code> (Kardinalität [1]): Eindeutige Kennung der UCM-Instanz als Zeichenkette.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Als statisches Metamodell-Klassendiagramm bildet die Darstellung keinen prozeduralen Ablauf ab.\n</li><li><strong>Laufzeit-Bezug:</strong>\n<ul class=\"fig-list\"><li>Der statisch konfigurierte <code>identifier</code> dient zur Laufzeit dem Routing und Dispatching von Aktualisierungspaketen.\n</li><li>In heterogenen Multi-UCM-Architekturen (z. B. zentraler <em>Vehicle Update Manager</em> steuert mehrere lokale <em>Target-UCMs</em>) prüft der UCM-Daemon bei eingehenden Software-Paketen, ob das Paket für seinen konfigurierten <code>identifier</code> bestimmt ist, bevor die Update-Zustandsmaschine (Transferring, Processing, Activating) initiiert wird.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Manifest-Erstellung &amp; XML-Schema:</strong>\n<ul class=\"fig-list\"><li>Im ARXML des <em>Machine Manifests</em> ist pro UCM-Dienstinstanz ein <code>&lt;UCM-MODULE-INSTANTIATION&gt;</code> unterhalb der jeweiligen <code>&lt;MACHINE&gt;</code> anzulegen.\n</li><li>Der Pfad erfordert einen gültigen <code>&lt;SHORT-NAME&gt;</code> (geerbt von <code>Identifiable</code>) und zwingend das Element <code>&lt;IDENTIFIER&gt;</code> als String.\n</li></ul>\n</li><li><strong>Stack- &amp; Integrator-Relevanz:</strong>\n<ul class=\"fig-list\"><li><strong>Generatoren / Backend:</strong> Manifest-Generatoren mappen <code>identifier</code> direkt in Konfigurations-Header, Initialisierungs-Payloads oder IPC/ara::com-Dienstinstanz-IDs des UCM-Daemons.\n</li><li><strong>Eindeutigkeit &amp; Flottenarchitektur:</strong> Der <code>identifier</code> muss im Adressbereich des Gesamtfahrzeug-Update-Managers eindeutig vergeben werden, um Fehlzustellungen von Software-Bundles und Rollbacks bei OTA-Kampagnen deterministisch zu verhindern.\n</li></ul>\n</li></ul>"}, {"id": "FIG-d1e4d1f49b74913e", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) der <em>AUTOSAR Adaptive Platform Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>).\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Definiert die formale Modellierung der Instanziierung des Functional Clusters <strong>UCM</strong> (<em>Update and Configuration Management</em>) im <em>Machine Manifest</em>. Es verankert UCM im allgemeinen Instanziierungsbaum der Adaptive-Plattform-Module und ermöglicht die eindeutige Adressierung spezifischer UCM-Instanzen im Fahrzeugnetzwerk (gemäß <code>RS_MANI_00023</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Identifiable</code></strong> <em>(abstrakt / Core-Metaklasse)</em>:\n<ul class=\"fig-list\"><li>Oberste Abstraktion für alle referenzierbaren AUTOSAR-Modellelemente.\n</li><li>Stellt Standardattribute bereit: <code>shortName</code> (Kardinalität [1], zwingend zur Pfadbildung), optionale UUIDs und Dokumentationsmetadaten.\n</li></ul>\n</li><li><strong><code>AdaptiveModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für die Konfiguration und Bereitstellung von Adaptive-Plattform-Basisdiensten bzw. Functional Clusters auf einer konkreten Ziel-Maschine (<code>Machine</code>).\n</li></ul>\n</li><li><strong><code>NonOsModuleInstantiation</code></strong> <em>(abstrakt, erbt via Generalisierung von <code>AdaptiveModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Differenziert Modulinstanzen, die keine direkten Betriebssystem-Prozesskonfigurationen (<code>OsModuleInstantiation</code> / Prozess-Scheduling) kapseln, sondern stack-interne Dienste und Functional-Cluster-Ressourcen parametrisieren.\n</li></ul>\n</li><li><strong><code>UcmModuleInstantiation</code></strong> <em>(konkret, erbt via Generalisierung von <code>NonOsModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Spezifische Manifest-Entität zur Repräsentation einer UCM-Instanz auf der jeweiligen Adaptive Platform Machine.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>+ identifier: String</code> (Kardinalität [1]): Eindeutige Kennung der UCM-Instanz als Zeichenkette.\n</li><li><code>+ maxNumberOfParallelTransfers: PositiveInteger [0..1]</code>: Optionale Obergrenze für die Anzahl parallel unterstützter Datentransfers (Software-Pakete) zur UCM-Instanz.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Als statisches Metamodell-Klassendiagramm bildet die Darstellung keinen prozeduralen Ablauf ab.\n</li><li><strong>Laufzeit-Bezug:</strong>\n<ul class=\"fig-list\"><li>Der statisch konfigurierte <code>identifier</code> dient zur Laufzeit dem Routing und Dispatching von Aktualisierungspaketen.\n</li><li>In heterogenen Multi-UCM-Architekturen (z. B. zentraler <em>Vehicle Update Manager</em> steuert mehrere lokale <em>Target-UCMs</em>) prüft der UCM-Daemon bei eingehenden Software-Paketen, ob das Paket für seinen konfigurierten <code>identifier</code> bestimmt ist, bevor die Update-Zustandsmaschine (Transferring, Processing, Activating) initiiert wird.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Manifest-Erstellung &amp; XML-Schema:</strong>\n<ul class=\"fig-list\"><li>Im ARXML des <em>Machine Manifests</em> ist pro UCM-Dienstinstanz ein <code>&lt;UCM-MODULE-INSTANTIATION&gt;</code> unterhalb der jeweiligen <code>&lt;MACHINE&gt;</code> anzulegen.\n</li><li>Neben <code>&lt;SHORT-NAME&gt;</code> und dem Pflichtelement <code>&lt;IDENTIFIER&gt;</code> kann optional <code>&lt;MAX-NUMBER-OF-PARALLEL-TRANSFERS&gt;</code> als ganzzahliger Wert konfiguriert werden.\n</li></ul>\n</li><li><strong>Stack- &amp; Integrator-Relevanz:</strong>\n<ul class=\"fig-list\"><li><strong>Ressourcenmanagement:</strong> <code>maxNumberOfParallelTransfers</code> dimensioniert die Puffer- und Thread-Ressourcen des UCM-Daemons für gleichzeitige Datenübertragungen. Fehlt die Angabe, greift das plattformspezifische Standardlimit.\n</li><li><strong>Eindeutigkeit &amp; Flottenarchitektur:</strong> Der <code>identifier</code> gewährleistet das eindeutige Ziel-Routing im Gesamtfahrzeugverbund.\n</li></ul>\n</li></ul>"}, {"id": "FIG-2b8832dbea56b0bb", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) der <em>AUTOSAR Adaptive Platform Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>).\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Definiert die formale Modellierung der Instanziierung des Functional Clusters <strong>UCM</strong> (<em>Update and Configuration Management</em>) im <em>Machine Manifest</em>. Es verankert UCM im allgemeinen Instanziierungsbaum der Adaptive-Plattform-Module und ermöglicht die eindeutige Adressierung spezifischer UCM-Instanzen im Fahrzeugnetzwerk (gemäß <code>RS_MANI_00023</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Identifiable</code></strong> <em>(abstrakt / Core-Metaklasse)</em>:\n<ul class=\"fig-list\"><li>Oberste Abstraktion für alle referenzierbaren AUTOSAR-Modellelemente.\n</li><li>Stellt Standardattribute bereit: <code>shortName</code> (Kardinalität [1], zwingend zur Pfadbildung), optionale UUIDs und Dokumentationsmetadaten.\n</li></ul>\n</li><li><strong><code>AdaptiveModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse für die Konfiguration und Bereitstellung von Adaptive-Plattform-Basisdiensten bzw. Functional Clusters auf einer konkreten Ziel-Maschine (<code>Machine</code>).\n</li></ul>\n</li><li><strong><code>NonOsModuleInstantiation</code></strong> <em>(abstrakt, erbt via Generalisierung von <code>AdaptiveModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Differenziert Modulinstanzen, die keine direkten Betriebssystem-Prozesskonfigurationen (<code>OsModuleInstantiation</code> / Prozess-Scheduling) kapseln, sondern stack-interne Dienste und Functional-Cluster-Ressourcen parametrisieren.\n</li></ul>\n</li><li><strong><code>UcmModuleInstantiation</code></strong> <em>(konkret, erbt via Generalisierung von <code>NonOsModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Spezifische Manifest-Entität zur Repräsentation einer UCM-Instanz auf der jeweiligen Adaptive Platform Machine.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>+ identifier: String</code> (Kardinalität [1]): Eindeutige Kennung der UCM-Instanz als Zeichenkette.\n</li><li><code>+ maxNumberOfParallelTransfers: PositiveInteger [0..1]</code>: Optionale Obergrenze für die Anzahl parallel unterstützter Datentransfers zur UCM-Instanz.\n</li><li><code>+ ucmSoftwareVersion: StrongRevisionLabelString [0..1]</code>: Optionale Versionsbezeichnung der UCM-Software gemäß formaler AUTOSAR-Revisionssyntax.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Als statisches Metamodell-Klassendiagramm bildet die Darstellung keinen prozeduralen Ablauf ab.\n</li><li><strong>Laufzeit-Bezug:</strong>\n<ul class=\"fig-list\"><li>Der statisch konfigurierte <code>identifier</code> dient zur Laufzeit dem Routing und Dispatching von Aktualisierungspaketen.\n</li><li>In heterogenen Multi-UCM-Architekturen (z. B. zentraler <em>Vehicle Update Manager</em> steuert mehrere lokale <em>Target-UCMs</em>) prüft der UCM-Daemon bei eingehenden Software-Paketen, ob das Paket für seinen konfigurierten <code>identifier</code> bestimmt ist, bevor die Update-Zustandsmaschine (Transferring, Processing, Activating) initiiert wird.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Manifest-Erstellung &amp; XML-Schema:</strong>\n<ul class=\"fig-list\"><li>Im ARXML des <em>Machine Manifests</em> ist pro UCM-Dienstinstanz ein <code>&lt;UCM-MODULE-INSTANTIATION&gt;</code> unterhalb der jeweiligen <code>&lt;MACHINE&gt;</code> anzulegen.\n</li><li>Neben <code>&lt;SHORT-NAME&gt;</code> und <code>&lt;IDENTIFIER&gt;</code> können optional <code>&lt;MAX-NUMBER-OF-PARALLEL-TRANSFERS&gt;</code> sowie <code>&lt;UCM-SOFTWARE-VERSION&gt;</code> deklariert werden.\n</li></ul>\n</li><li><strong>Stack- &amp; Integrator-Relevanz:</strong>\n<ul class=\"fig-list\"><li><strong>Software-Inventarisierung:</strong> <code>ucmSoftwareVersion</code> ermöglicht es Diagnose-Diensten und dem Fahrzeug-Update-Manager, die Version des UCM-Stacks selbst abzufragen und modellbasiert abzugleichen.\n</li><li><strong>Ressourcenmanagement:</strong> <code>maxNumberOfParallelTransfers</code> begrenzt die parallele Ausführung von Transfer-Vorgängen zur Absicherung von Speicher- und Rechenressourcen.\n</li><li><strong>Eindeutigkeit &amp; Flottenarchitektur:</strong> Der <code>identifier</code> sichert die eindeutige Adressierbarkeit der Instanz.\n</li></ul>\n</li></ul>"}, {"id": "FIG-1b967bfda8374898", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) der <em>AUTOSAR Adaptive Platform Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>).\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Modellierung der verteilten UCM-Architektur (<em>Update and Configuration Management</em>) im <em>Machine Manifest</em>. Das Metamodell differenziert zwischen übergeordneter Orchestrierung (<code>UcmMasterModuleInstantiation</code>) und ausführenden lokalen Instanzen (<code>UcmSubordinateModuleInstantiation</code>) und etabliert konfigurierbare Wiederholungsstrategien (<code>UcmRetryStrategy</code>) zur Absicherung robuster Software-Update-Prozesse.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>AdaptiveModuleInstantiation</code></strong> <em>(abstrakt, Stereotyp <code>«AtpStructureElement»</code>)</em>:\n<ul class=\"fig-list\"><li>Basisklasse für alle Modulinstanziierungen der Adaptive Platform im Machine Manifest.\n</li></ul>\n</li><li><strong><code>NonOsModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>AdaptiveModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Kapselt plattformspezifische, betriebssystemunabhängige funktionale Cluster.\n</li></ul>\n</li><li><strong><code>UcmModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>NonOsModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Gemeinsame Basisklasse für UCM-Instanzen.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>+ identifier: String [0..1]</code>: Optionale Kennung der UCM-Instanz im Fahrzeugnetzwerk.\n</li><li><code>+ maxBlockSize: PositiveInteger [0..1]</code>: Maximale Blockgröße in Bytes für Paketdatenblöcke bei der Übertragung.\n</li><li><code>+ version: StrongRevisionLabelString [0..1]</code>: Versionsbezeichnung der UCM-Implementierung.\n</li></ul>\n</li></ul>\n</li><li><strong><code>UcmSubordinateModuleInstantiation</code></strong> <em>(konkret, spezialisiert <code>UcmModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert eine untergeordnete UCM-Instanz, die Software-Pakete auf einer Zielmaschine empfängt, verifiziert und ausführt.\n</li><li><strong>Kompositionen zu <code>UcmRetryStrategy</code>:</strong>\n<ul class=\"fig-list\"><li><code>+prepareRollback</code> [0..1]: Wiederholungsstrategie für die Rollback-Vorbereitungsphase.\n</li><li><code>+prepareUpdate</code> [0..1]: Wiederholungsstrategie für die Update-Vorbereitungsphase.\n</li><li><code>+verifyUpdate</code> [0..1]: Wiederholungsstrategie für die Verifikationsphase.\n</li></ul>\n</li></ul>\n</li><li><strong><code>UcmMasterModuleInstantiation</code></strong> <em>(konkret, spezialisiert <code>UcmModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert die übergeordnete UCM-Master-Instanz zur Orchestrierung von Flotten- bzw. Fahrzeug-Updates.\n</li><li><strong>Kompositionen zu <code>UcmRetryStrategy</code>:</strong>\n<ul class=\"fig-list\"><li><code>+blockInconsistent</code> [0..1]: Strategie bei Inkonsistenz empfangener oder übertragener Datenblöcke.\n</li><li><code>+serviceBusy</code> [0..1]: Strategie bei temporärer Nichtverfügbarkeit bzw. Überlastung eines UCM-Dienstes.\n</li><li><code>+updateSessionRejected</code> [0..1]: Strategie bei Zurückweisung einer Update-Sitzung.\n</li></ul>\n</li></ul>\n</li><li><strong><code>UcmRetryStrategy</code></strong> <em>(konkret, Stereotyp <code>«Identifiable»</code>)</em>:\n<ul class=\"fig-list\"><li>Kapselt Parameter für automatische Wiederholungsversuche bei Fehlern.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>+ maximumNumberOfRetries: PositiveInteger [0..1]</code>: Maximale Anzahl aufeinanderfolgender Wiederholungsversuche.\n</li><li><code>+ retryIntervalTime: TimeValue [0..1]</code>: Zeitspanne zwischen zwei Wiederholungsversuchen.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Als statisches Metamodell-Klassendiagramm bildet die Darstellung keinen vollständigen Sequenzablauf ab, definiert aber die Kontrollfluss-Parameter für die Fehlerbehandlung zur Laufzeit.\n</li><li><strong>Laufzeit-Bezug &amp; Retry-Verhalten:</strong>\n<ul class=\"fig-list\"><li><strong>Subordinate-Zustandsübergänge:</strong> Schlagen Phasen wie <code>prepareUpdate</code>, <code>verifyUpdate</code> oder <code>prepareRollback</code> auf einer untergeordneten UCM-Instanz fehl, steuert die zugeordnete <code>UcmRetryStrategy</code> nach Wartezeit (<code>retryIntervalTime</code>) automatisierte erneute Versuche bis zum Limit <code>maximumNumberOfRetries</code>.\n</li><li><strong>Master-Orchestrierung:</strong> Tritt beim Master ein Fehler auf (z. B. <code>serviceBusy</code>, <code>blockInconsistent</code> oder <code>updateSessionRejected</code>), bricht der Master den Gesamtprozess nicht unmittelbar ab, sondern initiiert programmierte Wiederholungen gemäß der konfigurierten Retry-Strategie.\n</li><li><strong>Paketübertragung:</strong> <code>maxBlockSize</code> begrenzt die Payload-Größe bei iterativen Block-Transfers (<code>TransferData</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Manifest-Erstellung &amp; XML-Schema:</strong>\n<ul class=\"fig-list\"><li><code>&lt;UCM-MODULE-INSTANTIATION&gt;</code> ist abstrakt; im Machine Manifest sind stattdessen konkrete Instanzen von <code>&lt;UCM-MASTER-MODULE-INSTANTIATION&gt;</code> oder <code>&lt;UCM-SUBORDINATE-MODULE-INSTANTIATION&gt;</code> anzulegen.\n</li><li>Das Attribut <code>identifier</code> ist optional (<code>[0..1]</code>), <code>maxBlockSize</code> und <code>version</code> können optional auf Basisebene deklariert werden.\n</li><li>Wiederholungsstrategien werden als eingebettete <code>&lt;UCM-RETRY-STRATEGY&gt;</code>-Elemente unter den spezifischen Rollenpfaden (z. B. <code>&lt;PREPARE-UPDATE&gt;</code>, <code>&lt;SERVICE-BUSY&gt;</code>) konfiguriert.\n</li></ul>\n</li><li><strong>Stack- &amp; Integrator-Relevanz:</strong>\n<ul class=\"fig-list\"><li><strong>Fehlertoleranz:</strong> Integratoren müssen Timeouts und Retry-Zyklen aufeinander abstimmen, damit Retry-Schleifen von Subordinates nicht zu vorzeitigen Timeouts des Masters führen.\n</li><li><strong>Netzwerkoptimierung:</strong> <code>maxBlockSize</code> muss an die MTU und Puffergrößen des zugrundeliegenden Transportprotokolls angepasst werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-90c20195e857812e", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) der <em>AUTOSAR Adaptive Platform Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>).\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Modellierung der verteilten UCM-Architektur (<em>Update and Configuration Management</em>) im <em>Machine Manifest</em>. Das Metamodell differenziert zwischen übergeordneter Orchestrierung (<code>UcmMasterModuleInstantiation</code>) und ausführenden lokalen Instanzen (<code>UcmSubordinateModuleInstantiation</code>) und etabliert konfigurierbare Wiederholungsstrategien (<code>UcmRetryStrategy</code>) zur Absicherung robuster Software-Update-Prozesse.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>AdaptiveModuleInstantiation</code></strong> <em>(abstrakt, Stereotyp <code>«AtpStructureElement»</code>)</em>:\n<ul class=\"fig-list\"><li>Basisklasse für alle Modulinstanziierungen der Adaptive Platform im Machine Manifest.\n</li></ul>\n</li><li><strong><code>NonOsModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>AdaptiveModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Kapselt plattformspezifische, betriebssystemunabhängige funktionale Cluster.\n</li></ul>\n</li><li><strong><code>UcmModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>NonOsModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Gemeinsame Basisklasse für UCM-Instanzen.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>+ identifier: String [0..1]</code>: Optionale Kennung der UCM-Instanz im Fahrzeugnetzwerk.\n</li><li><code>+ maxBlockSize: PositiveInteger [0..1]</code>: Maximale Blockgröße in Bytes für Paketdatenblöcke bei der Übertragung.\n</li><li><code>+ version: StrongRevisionLabelString [0..1]</code>: Versionsbezeichnung der UCM-Implementierung.\n</li></ul>\n</li></ul>\n</li><li><strong><code>UcmSubordinateModuleInstantiation</code></strong> <em>(konkret, spezialisiert <code>UcmModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert eine untergeordnete UCM-Instanz zur lokalen Paketverarbeitung und -aktivierung.\n</li><li><strong>Attribut:</strong>\n<ul class=\"fig-list\"><li><code>+ maxAvailablePersistencyStorageSpace: PositiveInteger [0..1]</code>: Maximal verfügbarer persistenter Speicherplatz (in Bytes), der für Software-Pakete und persistente Daten reserviert ist.\n</li></ul>\n</li><li><strong>Kompositionen zu <code>UcmRetryStrategy</code>:</strong>\n<ul class=\"fig-list\"><li><code>+prepareRollback</code> [0..1]: Wiederholungsstrategie für die Rollback-Vorbereitungsphase.\n</li><li><code>+prepareUpdate</code> [0..1]: Wiederholungsstrategie für die Update-Vorbereitungsphase.\n</li><li><code>+verifyUpdate</code> [0..1]: Wiederholungsstrategie für die Verifikationsphase.\n</li></ul>\n</li></ul>\n</li><li><strong><code>UcmMasterModuleInstantiation</code></strong> <em>(konkret, spezialisiert <code>UcmModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert die übergeordnete UCM-Master-Instanz zur Orchestrierung von Flotten- bzw. Fahrzeug-Updates.\n</li><li><strong>Kompositionen zu <code>UcmRetryStrategy</code>:</strong>\n<ul class=\"fig-list\"><li><code>+blockInconsistent</code> [0..1]: Strategie bei Inkonsistenz empfangener oder übertragener Datenblöcke.\n</li><li><code>+serviceBusy</code> [0..1]: Strategie bei temporärer Nichtverfügbarkeit bzw. Überlastung eines UCM-Dienstes.\n</li><li><code>+updateSessionRejected</code> [0..1]: Strategie bei Zurückweisung einer Update-Sitzung.\n</li></ul>\n</li></ul>\n</li><li><strong><code>UcmRetryStrategy</code></strong> <em>(konkret, Stereotyp <code>«Identifiable»</code>)</em>:\n<ul class=\"fig-list\"><li>Kapselt Parameter für automatische Wiederholungsversuche bei Fehlern.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>+ maximumNumberOfRetries: PositiveInteger [0..1]</code>: Maximale Anzahl aufeinanderfolgender Wiederholungsversuche.\n</li><li><code>+ retryIntervalTime: TimeValue [0..1]</code>: Zeitspanne zwischen zwei Wiederholungsversuchen.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Als statisches Metamodell-Klassendiagramm bildet die Darstellung keinen vollständigen Sequenzablauf ab, definiert aber die Kontrollfluss-Parameter für die Fehlerbehandlung zur Laufzeit.\n</li><li><strong>Laufzeit-Bezug &amp; Retry-Verhalten:</strong>\n<ul class=\"fig-list\"><li><strong>Subordinate-Zustandsübergänge:</strong> Schlagen Phasen wie <code>prepareUpdate</code>, <code>verifyUpdate</code> oder <code>prepareRollback</code> auf einer untergeordneten UCM-Instanz fehl, steuert die zugeordnete <code>UcmRetryStrategy</code> nach Wartezeit (<code>retryIntervalTime</code>) automatisierte erneute Versuche bis zum Limit <code>maximumNumberOfRetries</code>.\n</li><li><strong>Master-Orchestrierung:</strong> Tritt beim Master ein Fehler auf (z. B. <code>serviceBusy</code>, <code>blockInconsistent</code> oder <code>updateSessionRejected</code>), bricht der Master den Gesamtprozess nicht unmittelbar ab, sondern initiiert programmierte Wiederholungen gemäß der konfigurierten Retry-Strategie.\n</li><li><strong>Paketübertragung:</strong> <code>maxBlockSize</code> begrenzt die Payload-Größe bei iterativen Block-Transfers (<code>TransferData</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Manifest-Erstellung &amp; XML-Schema:</strong>\n<ul class=\"fig-list\"><li>Unter <code>&lt;UCM-SUBORDINATE-MODULE-INSTANTIATION&gt;</code> kann optional das Element <code>&lt;MAX-AVAILABLE-PERSISTENCY-STORAGE-SPACE&gt;</code> als ganzzahliger Wert konfiguriert werden.\n</li><li>Die restliche XML-Struktur für Master, Subordinate und Retry-Strategien bleibt unverändert.\n</li></ul>\n</li><li><strong>Stack- &amp; Integrator-Relevanz:</strong>\n<ul class=\"fig-list\"><li><strong>Speichervalidierung:</strong> Integratoren und Update-Tools können anhand von <code>maxAvailablePersistencyStorageSpace</code> bereits vor Beginn eines Transfers prüfen, ob der auf der Zielmaschine zugewiesene Speicherplatz für das auszurollende Software-Paket ausreicht, um Speicherüberläufe zur Laufzeit abzuwenden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-83cd2b631bb1246e", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) der <em>AUTOSAR Adaptive Platform Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>).\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Modellierung der verteilten UCM-Architektur (<em>Update and Configuration Management</em>) im <em>Machine Manifest</em>. Das Metamodell differenziert zwischen übergeordneter Orchestrierung (<code>UcmMasterModuleInstantiation</code>) und ausführenden lokalen Instanzen (<code>UcmSubordinateModuleInstantiation</code>) und etabliert konfigurierbare Wiederholungsstrategien (<code>UcmRetryStrategy</code>) zur Absicherung robuster Software-Update-Prozesse.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>AdaptiveModuleInstantiation</code></strong> <em>(abstrakt, Stereotyp <code>«AtpStructureElement»</code>)</em>:\n<ul class=\"fig-list\"><li>Basisklasse für alle Modulinstanziierungen der Adaptive Platform im Machine Manifest.\n</li></ul>\n</li><li><strong><code>NonOsModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>AdaptiveModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Kapselt plattformspezifische, betriebssystemunabhängige funktionale Cluster.\n</li></ul>\n</li><li><strong><code>UcmModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>NonOsModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Gemeinsame Basisklasse für UCM-Instanzen.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>+ identifier: String [0..1]</code>: Optionale Kennung der UCM-Instanz im Fahrzeugnetzwerk.\n</li><li><code>+ maxBlockSize: PositiveInteger [0..1]</code>: Maximale Blockgröße in Bytes für Paketdatenblöcke bei der Übertragung.\n</li><li><code>+ version: StrongRevisionLabelString [0..1]</code>: Versionsbezeichnung der UCM-Implementierung.\n</li></ul>\n</li></ul>\n</li><li><strong><code>UcmSubordinateModuleInstantiation</code></strong> <em>(konkret, spezialisiert <code>UcmModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert eine untergeordnete UCM-Instanz zur lokalen Paketverarbeitung und -aktivierung.\n</li><li><strong>Attribut:</strong>\n<ul class=\"fig-list\"><li><code>+ maxAvailablePersistencyStorageSpace: PositiveInteger [0..1]</code>: Maximal verfügbarer persistenter Speicherplatz in Bytes.\n</li></ul>\n</li><li><strong>Kompositionen zu <code>UcmRetryStrategy</code>:</strong>\n<ul class=\"fig-list\"><li><code>+prepareRollback</code> [0..1]: Wiederholungsstrategie für die Rollback-Vorbereitungsphase.\n</li><li><code>+prepareUpdate</code> [0..1]: Wiederholungsstrategie für die Update-Vorbereitungsphase.\n</li><li><code>+verifyUpdate</code> [0..1]: Wiederholungsstrategie für die Verifikationsphase.\n</li></ul>\n</li></ul>\n</li><li><strong><code>UcmMasterModuleInstantiation</code></strong> <em>(konkret, spezialisiert <code>UcmModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert die übergeordnete UCM-Master-Instanz zur Orchestrierung von Flotten- bzw. Fahrzeug-Updates.\n</li><li><strong>Kompositionen zu <code>UcmRetryStrategy</code>:</strong>\n<ul class=\"fig-list\"><li><code>+blockInconsistent</code> [0..1]: Strategie bei Inkonsistenz empfangener oder übertragener Datenblöcke.\n</li><li><code>+serviceBusy</code> [0..1]: Strategie bei temporärer Nichtverfügbarkeit bzw. Überlastung eines UCM-Dienstes.\n</li><li><code>+ucmNotAvailableOnTheNetwork</code> [0..1]: Wiederholungsstrategie bei netzwerkweiter Unerreichbarkeit einer untergeordneten UCM-Instanz.\n</li><li><code>+updateSessionRejected</code> [0..1]: Strategie bei Zurückweisung einer Update-Sitzung.\n</li></ul>\n</li></ul>\n</li><li><strong><code>UcmRetryStrategy</code></strong> <em>(konkret, Stereotyp <code>«Identifiable»</code>)</em>:\n<ul class=\"fig-list\"><li>Kapselt Parameter für automatische Wiederholungsversuche bei Fehlern.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>+ maximumNumberOfRetries: PositiveInteger [0..1]</code>: Maximale Anzahl aufeinanderfolgender Wiederholungsversuche.\n</li><li><code>+ retryIntervalTime: TimeValue [0..1]</code>: Zeitspanne zwischen zwei Wiederholungsversuchen.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Als statisches Metamodell-Klassendiagramm bildet die Darstellung keinen vollständigen Sequenzablauf ab, definiert aber die Kontrollfluss-Parameter für die Fehlerbehandlung zur Laufzeit.\n</li><li><strong>Laufzeit-Bezug &amp; Retry-Verhalten:</strong>\n<ul class=\"fig-list\"><li><strong>Subordinate-Zustandsübergänge:</strong> Schlagen Phasen wie <code>prepareUpdate</code>, <code>verifyUpdate</code> oder <code>prepareRollback</code> auf einer untergeordneten UCM-Instanz fehl, steuert die zugeordnete <code>UcmRetryStrategy</code> nach Wartezeit (<code>retryIntervalTime</code>) automatisierte erneute Versuche bis zum Limit <code>maximumNumberOfRetries</code>.\n</li><li><strong>Master-Orchestrierung &amp; Netzwerkausfälle:</strong> Kann der Master eine untergeordnete UCM-Instanz im Netzwerk temporär nicht erreichen (z. B. Verbindungsunterbrechung oder verzögerter Start), greift die Wiederholungsstrategie <code>ucmNotAvailableOnTheNetwork</code>. Erst nach Erschöpfen der konfigurierten Versuche bricht die Kampagne ab.\n</li><li><strong>Weitere Master-Fehlerstrategien:</strong> Bei <code>serviceBusy</code>, <code>blockInconsistent</code> oder <code>updateSessionRejected</code> steuern die jeweiligen Retry-Strategien das automatisierte Wiederaufsetzen des Update-Dialogs.\n</li><li><strong>Paketübertragung:</strong> <code>maxBlockSize</code> begrenzt die Payload-Größe bei iterativen Block-Transfers (<code>TransferData</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Manifest-Erstellung &amp; XML-Schema:</strong>\n<ul class=\"fig-list\"><li>Unter <code>&lt;UCM-MASTER-MODULE-INSTANTIATION&gt;</code> kann nun zusätzlich die Rolle <code>&lt;UCM-NOT-AVAILABLE-ON-THE-NETWORK&gt;</code> mit einer eingebetteten <code>&lt;UCM-RETRY-STRATEGY&gt;</code> (mit <code>&lt;MAXIMUM-NUMBER-OF-RETRIES&gt;</code> und <code>&lt;RETRY-INTERVAL-TIME&gt;</code>) konfiguriert werden.\n</li></ul>\n</li><li><strong>Stack- &amp; Integrator-Relevanz:</strong>\n<ul class=\"fig-list\"><li><strong>Netzwerk-Robustheit:</strong> Integratoren können über <code>ucmNotAvailableOnTheNetwork</code> gezielt transiente Netzwerkstörungen oder Boot-Verzögerungen entfernter Steuergeräte abfangen, ohne dass Kampagnen sofort als fehlgeschlagen markiert werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-edc4d3e2544830f8", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) der <em>AUTOSAR Adaptive Platform Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>).\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Modellierung der verteilten UCM-Architektur (<em>Update and Configuration Management</em>) im <em>Machine Manifest</em>. Das Metamodell differenziert zwischen übergeordneter Orchestrierung (<code>UcmMasterModuleInstantiation</code>) und ausführenden lokalen Instanzen (<code>UcmSubordinateModuleInstantiation</code>) und etabliert konfigurierbare Wiederholungsstrategien (<code>UcmRetryStrategy</code>) zur Absicherung robuster Software-Update-Prozesse.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>AdaptiveModuleInstantiation</code></strong> <em>(abstrakt, Stereotyp <code>«AtpStructureElement»</code>)</em>:\n<ul class=\"fig-list\"><li>Basisklasse für alle Modulinstanziierungen der Adaptive Platform im Machine Manifest.\n</li></ul>\n</li><li><strong><code>NonOsModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>AdaptiveModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Kapselt plattformspezifische, betriebssystemunabhängige funktionale Cluster.\n</li></ul>\n</li><li><strong><code>UcmModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>NonOsModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Gemeinsame Basisklasse für UCM-Instanzen.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>+ identifier: String [0..1]</code>: Optionale Kennung der UCM-Instanz im Fahrzeugnetzwerk.\n</li><li><code>+ maxBlockSize: PositiveInteger [0..1]</code>: Maximale Blockgröße in Bytes für Paketdatenblöcke bei der Übertragung.\n</li><li><code>+ version: StrongRevisionLabelString [0..1]</code>: Versionsbezeichnung der UCM-Implementierung.\n</li></ul>\n</li></ul>\n</li><li><strong><code>UcmSubordinateModuleInstantiation</code></strong> <em>(konkret, spezialisiert <code>UcmModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert eine untergeordnete UCM-Instanz zur lokalen Paketverarbeitung und -aktivierung.\n</li><li><strong>Attribut:</strong>\n<ul class=\"fig-list\"><li><code>+ maxAvailablePersistencyStorageSpace: PositiveInteger [0..1]</code>: Maximal verfügbarer persistenter Speicherplatz in Bytes.\n</li></ul>\n</li><li><strong>Kompositionen zu <code>UcmRetryStrategy</code>:</strong>\n<ul class=\"fig-list\"><li><code>+prepareRollback</code> [0..1]: Wiederholungsstrategie für die Rollback-Vorbereitungsphase.\n</li><li><code>+prepareUpdate</code> [0..1]: Wiederholungsstrategie für die Update-Vorbereitungsphase.\n</li><li><code>+verifyUpdate</code> [0..1]: Wiederholungsstrategie für die Verifikationsphase.\n</li></ul>\n</li></ul>\n</li><li><strong><code>UcmMasterModuleInstantiation</code></strong> <em>(konkret, spezialisiert <code>UcmModuleInstantiation</code>)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert die übergeordnete UCM-Master-Instanz zur Orchestrierung von Flotten- bzw. Fahrzeug-Updates.\n</li><li><strong>Kompositionen zu <code>UcmRetryStrategy</code>:</strong>\n<ul class=\"fig-list\"><li><code>+blockInconsistent</code> [0..1]: Strategie bei Inkonsistenz empfangener oder übertragener Datenblöcke.\n</li><li><code>+serviceBusy</code> [0..1]: Strategie bei temporärer Nichtverfügbarkeit bzw. Überlastung eines UCM-Dienstes.\n</li><li><code>+ucmNotAvailableOnTheNetwork</code> [0..1]: Wiederholungsstrategie bei netzwerkweiter Unerreichbarkeit einer untergeordneten UCM-Instanz.\n</li><li><code>+updateSessionRejected</code> [0..1]: Strategie bei Zurückweisung einer Update-Sitzung.\n</li></ul>\n</li></ul>\n</li><li><strong><code>UcmRetryStrategy</code></strong> <em>(konkret, Stereotyp <code>«Identifiable»</code>)</em>:\n<ul class=\"fig-list\"><li>Kapselt Parameter für automatische Wiederholungsversuche bei Fehlern.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>+ maximumNumberOfRetries: PositiveInteger [0..1]</code>: Maximale Anzahl aufeinanderfolgender Wiederholungsversuche.\n</li><li><code>+ retryIntervalTime: TimeValue [0..1]</code>: Zeitspanne zwischen zwei Wiederholungsversuchen.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Als statisches Metamodell-Klassendiagramm bildet die Darstellung keinen vollständigen Sequenzablauf ab, definiert aber die Kontrollfluss-Parameter für die Fehlerbehandlung zur Laufzeit.\n</li><li><strong>Laufzeit-Bezug &amp; Retry-Verhalten:</strong>\n<ul class=\"fig-list\"><li><strong>Subordinate-Zustandsübergänge:</strong> Schlagen Phasen wie <code>prepareUpdate</code>, <code>verifyUpdate</code> oder <code>prepareRollback</code> auf einer untergeordneten UCM-Instanz fehl, steuert die zugeordnete <code>UcmRetryStrategy</code> nach Wartezeit (<code>retryIntervalTime</code>) automatisierte erneute Versuche bis zum Limit <code>maximumNumberOfRetries</code>.\n</li><li><strong>Master-Orchestrierung &amp; Netzwerkausfälle:</strong> Kann der Master eine untergeordnete UCM-Instanz im Netzwerk temporär nicht erreichen (z. B. Verbindungsunterbrechung oder verzögerter Start), greift die Wiederholungsstrategie <code>ucmNotAvailableOnTheNetwork</code>. Erst nach Erschöpfen der konfigurierten Versuche bricht die Kampagne ab.\n</li><li><strong>Weitere Master-Fehlerstrategien:</strong> Bei <code>serviceBusy</code>, <code>blockInconsistent</code> oder <code>updateSessionRejected</code> steuern die jeweiligen Retry-Strategien das automatisierte Wiederaufsetzen des Update-Dialogs.\n</li><li><strong>Paketübertragung:</strong> <code>maxBlockSize</code> begrenzt die Payload-Größe bei iterativen Block-Transfers (<code>TransferData</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Manifest-Erstellung &amp; XML-Schema:</strong>\n<ul class=\"fig-list\"><li>Unter <code>&lt;UCM-MASTER-MODULE-INSTANTIATION&gt;</code> kann nun zusätzlich die Rolle <code>&lt;UCM-NOT-AVAILABLE-ON-THE-NETWORK&gt;</code> mit einer eingebetteten <code>&lt;UCM-RETRY-STRATEGY&gt;</code> (mit <code>&lt;MAXIMUM-NUMBER-OF-RETRIES&gt;</code> und <code>&lt;RETRY-INTERVAL-TIME&gt;</code>) konfiguriert werden.\n</li></ul>\n</li><li><strong>Stack- &amp; Integrator-Relevanz:</strong>\n<ul class=\"fig-list\"><li><strong>Netzwerk-Robustheit:</strong> Integratoren können über <code>ucmNotAvailableOnTheNetwork</code> gezielt transiente Netzwerkstörungen oder Boot-Verzögerungen entfernter Steuergeräte abfangen, ohne dass Kampagnen sofort als fehlgeschlagen markiert werden.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-d84cc1eca92e394c", "to": "FIG-f5e1a0b0f072564c", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>UcmModuleInstantiation</code>: Typ des Attributs <code>identifier</code> von <code>PositiveInteger</code> zu <code>String</code> geändert.\n</li></ul>"}, {"from": "FIG-f5e1a0b0f072564c", "to": "FIG-d1e4d1f49b74913e", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>UcmModuleInstantiation</code>: Attribut <code>maxNumberOfParallelTransfers: PositiveInteger [0..1]</code> neu hinzugefügt.\n</li></ul>"}, {"from": "FIG-d1e4d1f49b74913e", "to": "FIG-2b8832dbea56b0bb", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>UcmModuleInstantiation</code>: Attribut <code>ucmSoftwareVersion: StrongRevisionLabelString [0..1]</code> neu hinzugefügt.\n</li></ul>"}, {"from": "FIG-2b8832dbea56b0bb", "to": "FIG-1b967bfda8374898", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>AdaptiveModuleInstantiation</code>: Stereotyp <code>«AtpStructureElement»</code> ergänzt.\n</li><li><code>UcmModuleInstantiation</code>: Metaklasse als abstrakt deklariert (kursiver Name); Kardinalität von <code>identifier</code> von <code>[1]</code> auf <code>[0..1]</code> gelockert; Attribut <code>maxNumberOfParallelTransfers</code> entfernt; Attribut <code>maxBlockSize: PositiveInteger [0..1]</code> neu hinzugefügt; Attribut <code>ucmSoftwareVersion</code> zu <code>version: StrongRevisionLabelString [0..1]</code> umbenannt.\n</li><li><code>UcmMasterModuleInstantiation</code>: Neue Metaklasse eingeführt (spezialisiert <code>UcmModuleInstantiation</code>).\n</li><li><code>UcmSubordinateModuleInstantiation</code>: Neue Metaklasse eingeführt (spezialisiert <code>UcmModuleInstantiation</code>).\n</li><li><code>UcmRetryStrategy</code>: Neue Metaklasse eingeführt (Stereotyp <code>«Identifiable»</code>, Attribute <code>maximumNumberOfRetries: PositiveInteger [0..1]</code> und <code>retryIntervalTime: TimeValue [0..1]</code>).\n</li><li>Kompositionen von <code>UcmSubordinateModuleInstantiation</code> zu <code>UcmRetryStrategy</code> neu eingeführt: <code>prepareRollback</code> [0..1], <code>prepareUpdate</code> [0..1], <code>verifyUpdate</code> [0..1].\n</li><li>Kompositionen von <code>UcmMasterModuleInstantiation</code> zu <code>UcmRetryStrategy</code> neu eingeführt: <code>blockInconsistent</code> [0..1], <code>serviceBusy</code> [0..1], <code>updateSessionRejected</code> [0..1].\n</li></ul>"}, {"from": "FIG-1b967bfda8374898", "to": "FIG-90c20195e857812e", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>UcmSubordinateModuleInstantiation</code>: Attribut <code>maxAvailablePersistencyStorageSpace: PositiveInteger [0..1]</code> neu hinzugefügt.\n</li></ul>"}, {"from": "FIG-90c20195e857812e", "to": "FIG-83cd2b631bb1246e", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>UcmMasterModuleInstantiation</code>: Neue Kompositions-Rolle <code>ucmNotAvailableOnTheNetwork</code> [0..1] zu <code>UcmRetryStrategy</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-83cd2b631bb1246e", "to": "FIG-edc4d3e2544830f8", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
